// Industries hub (/industries/) runtime. HTML is generated by scripts/build-industries.mjs.
import { initSite, gsap, reduceMotion } from '../../ds/site.js';
import { Flip } from 'gsap/Flip';
import { $, $$, initHeadings, initMagnetic, initTilt, radioGroup } from './motion.js';
import { mountIndustryScene, IND_COLORS } from './scene-hero.js';
import { initTone, initVMarquee, initSecIndex, initHeroStage } from './r2.js';
import { cardFX, tiltGlare } from '../results/cardfx.js';
import './industry.css';
import './r2.css';

gsap.registerPlugin(Flip);
initSite();
const mm = gsap.matchMedia();
initHeadings(mm);
initMagnetic();
initTilt();

// Hero: the five industries orbit a core; clicking an emblem selects that tab (the tabs stay the accessible control)
let field = null;
const tabsForPick = $$('.picker__ind');
const scenePromise = mountIndustryScene($('[data-ind-scene]'), { variant: 'hub', onPick: (i) => tabsForPick[i]?.click() });
scenePromise.then((api) => (field = api));
initHeroStage($('[data-hero]'), scenePromise);
initTone();
initVMarquee();
initSecIndex();
$$('[data-tilt-card]').forEach((el) => tiltGlare(el, { rotate: false }));
cardFX($$('.hub-case__media'), { colorOf: (el) => IND_COLORS[el.closest('[data-industry]')?.dataset.industry] || '#0792c2' });
mm.add('(prefers-reduced-motion: no-preference)', () => {
  gsap.from('.orbit-legend li', { y: 16, opacity: 0, duration: 0.8, ease: 'expo.out', stagger: 0.06, delay: 0.6 });
  gsap.from('.leans__dot.is-on', { scale: 0, duration: 0.6, ease: 'back.out(2.4)', stagger: 0.05, scrollTrigger: { trigger: '[data-leans]', start: 'top 80%' } });
  gsap.from('.heat__cell', { scale: 0.3, opacity: 0, duration: 0.6, ease: 'expo.out', stagger: { each: 0.008, grid: [5, 12], from: 'start' }, scrollTrigger: { trigger: '[data-heat]', start: 'top 80%' } });
});

// 01 · Industry picker (tabs) + Residential/Commercial toggle
const picker = $('[data-picker]');
if (picker) {
  const panel = $('[data-picker-data]', picker);
  const data = JSON.parse(panel.dataset.pickerData);
  const tabs = $$('.picker__ind', picker);
  let ind = 0;
  let path = 'residential';
  const render = () => {
    const d = data[ind];
    panel.setAttribute('aria-labelledby', tabs[ind].id);
    $('[data-pk-tag]', panel).textContent = d.tagline.toUpperCase();
    $('[data-pk-money]', panel).textContent = d.money;
    $('[data-pk-pathname]', panel).textContent = path === 'residential' ? 'Residential' : 'Commercial';
    $('[data-pk-path]', panel).textContent = d[path];
    const a = $('[data-pk-link]', panel);
    a.href = `/industries/${d.slug}/#${path}`;
    a.firstElementChild.textContent = `Explore ${d.name}`;
    field?.setActive(ind);
    const n = String(ind + 1).padStart(2, '0');
    $$('[data-orbit-n], [data-orbit-num]').forEach((x) => (x.textContent = n));
    $('[data-orbit-name]').textContent = d.name;
    $('[data-orbit-tag]').textContent = d.tagline;
    $$('[data-legend]').forEach((li, k) => li.classList.toggle('is-on', k === ind));
    if (!reduceMotion) gsap.fromTo(panel.children, { y: 8, opacity: 0 }, { y: 0, opacity: 1, duration: 0.45, ease: 'expo.out', stagger: 0.04 });
  };
  radioGroup(tabs, (i) => ((ind = i), render()), 'aria-selected');
  radioGroup($$('[data-path]', picker), (i, b) => ((path = b.dataset.path), render()));
}

// 03 · Matrix column highlight (toggle)
const matrix = $('[data-matrix]');
if (matrix) {
  const btns = $$('.hub-matrix__ctl [data-col]');
  let current = -1;
  const hl = (i) => $$('[data-col]', matrix).forEach((c) => c.classList.toggle('is-hl', Number(c.dataset.col) === i));
  btns.forEach((b, i) =>
    b.addEventListener('click', () => {
      current = current === i ? -1 : i;
      btns.forEach((x, k) => x.setAttribute('aria-checked', String(k === current)));
      hl(current);
    }),
  );
  btns.forEach((b, i) =>
    b.addEventListener('keydown', (e) => {
      const d = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
      if (!d) return;
      e.preventDefault();
      const to = (i + d + btns.length) % btns.length;
      btns.forEach((x, k) => (x.tabIndex = k === to ? 0 : -1));
      btns[to].focus();
      btns[to].click();
    }),
  );
}

// 07 · Proof filter (Flip re-layout; honest "closest case" note)
const cases = $('[data-cases]');
if (cases) {
  const cards = $$('.hub-case', cases);
  const note = $('[data-cases-note]');
  radioGroup($$('[data-proof-filter] [data-filter]'), (i, b) => {
    const f = b.dataset.filter;
    const state = Flip.getState(cards);
    const match = cards.filter((c) => c.dataset.industry === f);
    cards.forEach((c) => {
      c.hidden = f !== 'all' && match.length > 0 && !match.includes(c);
      c.classList.toggle('is-closest', f !== 'all' && match.length === 0);
    });
    note.textContent = f !== 'all' && match.length === 0 ? `No ${b.textContent.split(' ·')[0]} case is published yet. These are the closest ones.` : '';
    if (!reduceMotion) Flip.from(state, { duration: 0.55, ease: 'power3.inOut', absolute: true, onEnter: (els) => gsap.fromTo(els, { opacity: 0, scale: 0.95 }, { opacity: 1, scale: 1, duration: 0.4 }), onLeave: (els) => gsap.to(els, { opacity: 0, duration: 0.25 }) });
  });
}

// 10 · Pick your industry → pre-filled partnership link
const pick = $('[data-pick-cta]');
if (pick) {
  const a = $('[data-pick-link]', pick);
  $$('input[name="hub-industry"]', pick).forEach((r) => r.addEventListener('change', () => (a.href = `/explore-partnership/?industry=${r.value}`)));
}
